// Plans and billing: the free tier, the $9/month paid plan, and the
// test-USDC payments that activate it.
//
// Pricing, from the adopted direction #5:
//   - Free: 25 responses a month across your forms; the runner shows the
//     "Built with OpenTypeform" badge.
//   - Paid ($9/month): 1,000 responses a month, unbranded.
//   - A payment buys 30 days, and is paid in test USDC — clearly labelled as
//     tests in the product, because that is what they are.
//
// How a payment is verified in the product itself: paying starts a payment
// record with its own receiving address (generated by lib/eth.js). The
// server reads the USDC balance of that address through a public node
// (lib/chain.js) and credits one 30-day extension per whole 9 USDC that
// arrived and has not been credited yet. Nothing is deleted or taken away
// when a plan lapses — collection just moves back to the free limits.
"use strict";

const fs = require("node:fs");
const path = require("node:path");
const { newReceivingKeys, addressForPrivateKey } = require("./eth");
const { DEFAULT_RPC_URL, DEFAULT_TOKEN, CHAIN_ID, NETWORK_NAME } = require("./chain");

const BILLING_FILE = "billing.json";
const PRICE_USDC = 9; // whole USDC per 30 days
const PRICE_UNITS = BigInt(PRICE_USDC) * 1_000_000n; // 6 decimals
const PAID_DAYS = 30;
const FREE_MONTHLY_LIMIT = 25;
const PAID_MONTHLY_LIMIT = 1000;

class Billing {
  constructor(dir) {
    this.file = path.join(dir, BILLING_FILE);
    this.records = {};
    this.load();
  }

  load() {
    try {
      const saved = JSON.parse(fs.readFileSync(this.file, "utf8"));
      // Re-derive every address from its key so a hand-edited file can never
      // point payments somewhere the product is not watching. A record whose
      // key cannot be derived is kept on its stored address rather than
      // dropped: dropping it would silently take away a paid entitlement.
      for (const [accountId, rec] of Object.entries(saved)) {
        const address = addressForPrivateKey(rec.privateKey);
        if (address) this.records[accountId] = { ...rec, address };
        else if (rec.address) this.records[accountId] = { ...rec };
        else console.error(`billing: record for ${accountId} has no usable key or address; kept as stored`);
      }
    } catch (err) {
      if (err.code !== "ENOENT") throw new Error(`could not read ${this.file}: ${err.message}`);
      this.records = {};
    }
  }

  save() {
    const tmp = this.file + ".tmp";
    fs.writeFileSync(tmp, JSON.stringify(this.records, null, 2));
    fs.renameSync(tmp, this.file);
  }

  recordFor(accountId) {
    return this.records[accountId] || null;
  }

  // Ensures the account has a receiving address and returns the payment
  // details the billing page shows.
  paymentDetails(accountId, rpcUrl) {
    let rec = this.records[accountId];
    if (!rec) {
      const keys = newReceivingKeys();
      rec = {
        privateKey: keys.privateKey,
        address: keys.address,
        creditedUnits: "0",
        paidUntil: null,
        createdAt: new Date().toISOString(),
      };
      this.records[accountId] = rec;
      this.save();
    }
    return {
      address: rec.address,
      amountUsdc: PRICE_USDC,
      amountUnits: PRICE_UNITS.toString(),
      chainId: CHAIN_ID,
      network: NETWORK_NAME,
      rpcUrl: rpcUrl || process.env.RPC_URL || DEFAULT_RPC_URL,
      token: process.env.USDC_ADDRESS || DEFAULT_TOKEN,
      test: true,
    };
  }

  // Reads the chain and credits whole payments that arrived since the last
  // credit. `readBalance` is injectable for tests; it defaults to the real
  // chain client. Returns the record after any credits.
  async checkPayment(accountId, readBalance) {
    const rec = this.records[accountId];
    if (!rec) return null;
    const read = readBalance || ((address) => require("./chain").tokenBalance({ address }));
    let balance;
    try {
      balance = await read(rec.address);
    } catch (err) {
      return { ...rec, available: false, error: String(err.message || err) };
    }
    let credited = BigInt(rec.creditedUnits || "0");
    let paidUntil = rec.paidUntil ? new Date(rec.paidUntil).getTime() : 0;
    const now = Date.now();
    // Each whole 9-USDC block beyond what was already credited buys 30 more
    // days, from the latest expiry if a plan is already active.
    while (balance - credited >= PRICE_UNITS) {
      credited += PRICE_UNITS;
      paidUntil = Math.max(paidUntil, now) + PAID_DAYS * 24 * 60 * 60 * 1000;
      rec.creditedUnits = credited.toString();
      rec.paidUntil = new Date(paidUntil).toISOString();
      rec.lastPaymentAt = new Date(now).toISOString();
      this.save();
    }
    return { ...rec, available: true, balanceUnits: balance.toString() };
  }

  // The plan as it is right now: paid only while the 30-day window runs.
  // `used` is the account's responses this calendar month.
  plan(accountId, used, now) {
    const rec = this.records[accountId];
    const paidActive = !!rec?.paidUntil && new Date(rec.paidUntil).getTime() > (now || Date.now());
    const tier = paidActive ? "paid" : "free";
    return {
      tier,
      paidUntil: rec?.paidUntil || null,
      limit: paidActive ? PAID_MONTHLY_LIMIT : FREE_MONTHLY_LIMIT,
      used: used || 0,
      priceUsdc: PRICE_USDC,
      paidDays: PAID_DAYS,
      freeLimit: FREE_MONTHLY_LIMIT,
      paidLimit: PAID_MONTHLY_LIMIT,
      network: NETWORK_NAME,
      token: process.env.USDC_ADDRESS || DEFAULT_TOKEN,
      rpcUrl: process.env.RPC_URL || DEFAULT_RPC_URL,
    };
  }

  // Whether collection is paused for this usage level, and by how much.
  paused(plan) {
    return plan.used >= plan.limit;
  }
}

// The first instant of the current UTC calendar month; monthly usage counts
// from here.
function monthStart(now) {
  const d = now ? new Date(now) : new Date();
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1)).toISOString();
}

module.exports = {
  Billing,
  monthStart,
  PRICE_USDC,
  PRICE_UNITS,
  PAID_DAYS,
  FREE_MONTHLY_LIMIT,
  PAID_MONTHLY_LIMIT,
};
